const ST30={sites:{},ask:{},rooms:{},ox0:null,peeps:{},cust:{},shells:{},looks:{},moved:[]};
// ---- the art: register each building (day and lit-window night) and each piece as a sprite
for(const [k,a] of Object.entries(ST30_ART)){const [uri,fw,fh,ax,ay,bw,chim,dw,ddx,steps,wallh,wins]=a;const src='mem:'+k;
  SPR[k]={src,fw,fh,ax,ay,foot:[-bw/2,-3.3,bw/2,0],bw,chim,door_w:dw,door_dx:ddx,steps,wallh,wins:wins||[],px:'ase'};
  const im=new Image();im.onload=()=>{IMG[src]=im;for(const s of Object.values(ST30.sites))if(s.base===k||s.base+'_n'===k)s.sig='';};im.src=uri;}
for(const [k,a] of Object.entries(ST30_PIECES)){const [uri,fw,fh,ax,ay,foot]=a;const src='mem:'+k;SPR[k]={src,fw,fh,ax,ay,foot};
  const im=new Image();im.onload=()=>{IMG[src]=im;for(const s of Object.values(ST30.sites))s.sig='';};im.src=uri;}
// ---- the lots: Market Row (north side of the main road east of the tavern, facing it), each town shop's own lot further
// along the row for its second building, and the west end of Wickham's high street for branches
const ST30_ROW=[90,101,112,123,134].map(x=>({x,z:-9}));
const ST30_AXLOT={mae:141.5,v_feed:156,v_forge:163,v_carp:170,v_bait:180.5,tavern:187.5,inn:210};
const ST30_WICK=[[93.6,43.6],[85.6,43.6],[77.6,43.6]];   // 8 m apart: 2.5 m and more between one branch's eaves and the next one's walls (planning rule 4), east of the lane at x 74   // west of the inn, so no neighbour stands across a front, and clear of the path the townsfolk take down the inn's side
const st30Hour=()=>S.hour||0;
const st30Free=()=>typeof free6==='function'&&free6();
// ---- signboards drawn over the door at runtime, in the kit's own letters. Before the painted sign: a raw plank lettered by
// hand in white paint, the letters wandering, a drip, two nails. The painted sign: a board in the trade's colours, bold gilt
// letters, a picture of the trade at each end, hung from iron brackets
const ST30_BOARD={stand:{face:'#2c3a30',top:'#587050',mid:'#405440',bot:'#1c2420',ink:'#f0b848',hi:'#fff0b0',sh:'#10160f',rim:'#c88a34'},
  kitchen:{face:'#1a3226',top:'#366044',mid:'#264834',bot:'#10201a',ink:'#fbe08a',hi:'#fffbe0',sh:'#08120c',rim:'#e2d4b0'},
  taproom:{face:'#40141e',top:'#7a2c30',mid:'#5a1c26',bot:'#200e18',ink:'#f0b848',hi:'#fff0b0',sh:'#14060a',rim:'#c88a34'}};
const st30H=(a,b)=>{const v=Math.sin(a*127.1+b*311.7)*43758.5453;return v-Math.floor(v);};
function st30Text(g,x,y,t,col,sh,o){const F=typeof PXFONT!=='undefined'?PXFONT:{};o=o||{};let i=0;
  for(const ch of t){const f=F[ch]||F[' ']||'';const dy=o.jit?Math.round(st30H(i,o.jit)*2-1):0;
    for(let j=0;j<5;j++)for(let k=0;k<3;k++)if(f[j*3+k]==='1'){const X=x+k,Y=y+j+dy;
      if(sh){g.fillStyle=sh;g.fillRect(X+1,Y+1,o.bold?2:1,1);}g.fillStyle=(o.hi&&j===0)?o.hi:col;g.fillRect(X,Y,1,1);if(o.bold)g.fillRect(X+1,Y,1,1);}
    x+=o.bold?5:4;i++;}}
function st30Emblem(g,x,y,trade){const R=(a,b,w,h,c)=>{g.fillStyle=c;g.fillRect(a,b,w,h);};
  if(trade==='stand'){R(x+1,y+2,5,4,'#c83a2e');R(x,y+3,7,2,'#c83a2e');R(x+2,y+6,3,1,'#8a2420');R(x+2,y+3,1,1,'#f08a70');R(x+3,y,1,2,'#4a2a14');R(x+4,y,2,1,'#6aa040');}
  else if(trade==='kitchen'){R(x,y+3,8,3,'#e8e2d0');R(x+1,y+6,6,1,'#a8a090');R(x+1,y+3,6,1,'#b8642a');R(x+2,y,1,2,'#e8e2d0');R(x+5,y,1,2,'#e8e2d0');R(x+3,y+1,1,1,'#e8e2d0');}
  else{R(x,y+1,5,6,'#d8962a');R(x,y+1,5,2,'#f6f0e0');R(x+5,y+3,2,1,'#c8c4b4');R(x+6,y+3,1,3,'#c8c4b4');R(x+5,y+5,2,1,'#c8c4b4');R(x,y+3,1,4,'#f0c060');}}
function st30Board(g,cx,y,text,style){const t=String(text||'').toUpperCase().replace(/[^A-Z0-9 &.]/g,'').replace(/\s+/g,' ').trim().slice(0,22);if(!t)return;
  const R=(x,y,w,h,c)=>{g.fillStyle=c;g.fillRect(x,y,w,h);};
  if(style==='plank'){   // a raw plank, lettered by hand
    const w=t.length*4+9,h=10,x0=Math.round(cx-w/2),y0=y;
    for(let yy=0;yy<=h;yy++)for(let xx=0;xx<=w;xx++){const n=st30H(xx>>2,yy+3);R(x0+xx,y0+yy,1,1,yy===0?'#b88a5a':yy===h?'#4a3018':(yy%4===2&&n>.55)?'#7a5432':n>.82?'#a0744a':'#8e6440');}
    R(x0-1,y0,1,h+1,'#1d1018');R(x0+w+1,y0,1,h+1,'#1d1018');R(x0,y0-1,w+1,1,'#1d1018');R(x0,y0+h+1,w+1,1,'#1d1018');
    R(x0+2,y0+5,1,1,'#2a2a30');R(x0+w-2,y0+4,1,1,'#2a2a30');   // nails
    st30Text(g,x0+5,y0+3,t,'#ece6d8',null,{jit:7});
    const d=x0+5+Math.floor(st30H(t.length,9)*Math.max(1,t.length-1))*4+1;R(d,y0+9,1,2,'#d8d0c0');   // a drip of paint
    return;}
  const C=ST30_BOARD[style]||ST30_BOARD.stand;const h=13,w=t.length*4+29,x0=Math.round(cx-w/2),y0=y-3;
  R(x0+8,y0-5,2,5,'#383a4a');R(x0+w-10,y0-5,2,5,'#383a4a');R(x0+6,y0-6,6,1,'#383a4a');R(x0+w-12,y0-6,6,1,'#383a4a');   // the brackets
  R(x0,y0,w+1,h+1,C.face);R(x0,y0,w+1,1,C.top);R(x0,y0+1,w+1,1,C.mid);R(x0,y0+h,w+1,1,C.bot);
  R(x0-1,y0,1,h+1,'#1d1018');R(x0+w+1,y0,1,h+1,'#1d1018');R(x0,y0-1,w+1,1,'#1d1018');R(x0,y0+h+1,w+1,1,'#1d1018');
  g.fillStyle=C.rim;for(let x=x0+2;x<=x0+w-2;x++){g.fillRect(x,y0+2,1,1);g.fillRect(x,y0+h-2,1,1);}for(let yy=y0+2;yy<=y0+h-2;yy++){g.fillRect(x0+2,yy,1,1);g.fillRect(x0+w-2,yy,1,1);}
  st30Emblem(g,x0+4,y0+3,style);st30Emblem(g,x0+w-11,y0+3,style);
  st30Text(g,x0+15,y0+4,t,C.ink,C.sh,{hi:C.hi});}
